<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import UButton from '@nuxt/ui/components/Button.vue';
import UInput from '@nuxt/ui/components/Input.vue';
import USelect from '@nuxt/ui/components/Select.vue';
import UTextarea from '@nuxt/ui/components/Textarea.vue';
import { state, workspaceAction } from '../store';
const current = computed(() => state.sessions?.records.find(item => item.id === state.sessions?.selected));
const definitionId = ref('none'), agent = ref(''), adapt = ref(false);
const definition = computed(() => state.definitions.find(item => item.id === definitionId.value));
const selectedAgent = computed(() => definition.value?.agents.find(item => item.name === agent.value));
watch(definitionId, () => { agent.value = definition.value?.agents.find(item => item.name === 'root')?.name ?? definition.value?.agents[0]?.name ?? ''; adapt.value = false; });
watch(agent, () => { adapt.value = false; });
const open = ref(false), title = ref(''), repository = ref(''), paths = ref(''), busy = ref(false), submitted = ref(false);
watch(() => state.unlocked, value => { if (!value) { title.value = ''; repository.value = ''; paths.value = ''; open.value = false; submitted.value = false; } });
async function run() { busy.value = true; try { const result = await workspaceAction('/api/taskboard', { title: title.value, instruction: state.draft, provider: current.value?.provider, ...(definition.value ? { definitionId: definition.value.id, agent: agent.value, useInstructionsOnly: adapt.value } : {}), repository: repository.value, paths: paths.value.split('\n').map(item => item.trim()).filter(Boolean) }); if (result) { submitted.value = true; open.value = false; state.draft = ''; } } finally { busy.value = false; } }
</script>
<template>
<div class="run-task"><div class="actions"><UButton color="neutral" variant="outline" icon="i-lucide-play" :disabled="!state.unlocked || !state.chat?.available || !state.draft.trim()" :aria-expanded="open" aria-controls="local-task-form" @click="open = !open; submitted = false">Run task</UButton><span class="muted">Produce a patch from your draft and approved files.</span></div><p v-if="submitted" role="status">File task queued in its own session. <RouterLink to="/history">Open your taskboard →</RouterLink></p><form v-if="open" id="local-task-form" class="settings-form" @submit.prevent="run"><h2>Prepare a local change</h2><p>A new task session uses the selected provider and receives your draft and snapshots of these files. The worker saves a patch for review. Your checkout is not changed, and tests are not run automatically.</p><p class="page-note">Provider: {{ state.settings?.providers.find(item => item.id === current?.provider)?.label ?? current?.provider }}. Choose a different provider by creating a new task first.</p><label for="file-task-definition">Agent definition for this file task</label><USelect id="file-task-definition" v-model="definitionId" :items="[{ value: 'none', label: 'No definition · use my instructions' }, ...state.definitions.map(item => ({ value: item.id, label: item.name }))]" class="w-full" /><template v-if="definition"><label for="file-task-agent">Agent</label><USelect id="file-task-agent" v-model="agent" :items="definition.agents.map(item => ({ value: item.name, label: item.name }))" class="w-full" /><details v-if="selectedAgent"><summary>Review agent instructions &amp; model</summary><p>{{ selectedAgent.model || 'Configured provider model' }}</p><pre>{{ selectedAgent.instruction }}</pre></details><div v-if="selectedAgent?.requiresAdaptation" class="compatibility-note"><strong>Instructions-only adaptation</strong><ul><li v-for="issue in selectedAgent.unsupported" :key="issue">{{ issue }}</li></ul><label class="check-label"><input v-model="adapt" type="checkbox"> Use instructions only. I accept the omitted features listed above.</label></div></template><label for="local-title">Task title</label><UInput id="local-title" v-model="title" required maxlength="200" class="w-full" /><label for="local-repository">Repository directory on the worker machine</label><UInput id="local-repository" v-model="repository" required placeholder="/home/you/project" class="w-full" /><label for="local-paths">Approved files · one relative path per line</label><UTextarea id="local-paths" v-model="paths" required placeholder="src/example.ts" class="w-full" /><p class="page-note">Only these text files are sent to the provider. Up to 32 files and 48,000 characters total. New files are supported.</p><UButton type="submit" :loading="busy" :disabled="!state.draft.trim() || (selectedAgent?.requiresAdaptation && !adapt)">Queue file task</UButton></form></div>
</template>
